import base64
from pathlib import Path
p = Path("webcms/admin/admin_api.py")
txt = p.read_text()

# Find the start of update_page and end of delete_page
start = txt.find("    def update_page(self, request: Request, page_id: str) -> Response:")
end = txt.find("    def list_posts(self, request: Request) -> Response:")
if start == -1 or end == -1:
    print("markers not found", start, end)
    raise SystemExit(1)

replacement = base64.b64decode("").decode()

txt = txt[:start] + replacement + txt[end:]
p.write_text(txt)
print("fixed update/delete methods")